def chainInspectionTotalReceipt(head):
    a=head
    out=[]
    node=a
    while node:
        out.append(node.val)
        node=node.next
    return sum(out)


java
class Solution {
  public int chainInspectionTotalReceipt(ListNode head) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {for(ListNode node=a;node!=null;node=node.next)out.add(node.val);}
    int answer=0;for(int x:out)answer+=x;return answer;
  }
}
